"""mage.json -> keymap/mage_frames.h (PROGMEM arrays used by render_mage in keymap.c)."""

import json

mage = json.load(open("mage.json"))
out = [
    "// Mage sprite, 32x88 px per frame (11 rows of the vertical screen, 32 bytes each).",
    "// Adapted from a 64x64 pixel-art reference: converted to 1 bit and narrowed to 32 px.",
    "// Generated by sprites/mage/make_header.py, do not edit by hand.",
    "#pragma once",
    "",
]
for name, frames in mage.items():
    assert all(len(f) == 352 for f in frames)
    out.append(f"static const char PROGMEM mage_{name}[{len(frames)}][MAGE_SIZE] = {{")
    for f in frames:
        rows = [", ".join(f"0x{b:02x}" for b in f[i : i + 16]) for i in range(0, len(f), 16)]
        out.append("    {\n        " + ",\n        ".join(rows) + "\n    },")
    out.append("};")
    out.append("")
open("../../keymap/mage_frames.h", "w", newline="\n").write("\n".join(out))
print({k: len(v) for k, v in mage.items()})
